fn post_tweet_id(item: &FeedItem) -> Option<u64> {
    as_post(item).map(|post| post.tweet_id)
}

fn first_served_adjacency(items: &[FeedItem], served: &HashSet<u64>) -> Option<(usize, Side)> {
    for (i, item) in items.iter().enumerate() {
        if !is_ad(item) {
